import{_ as e,o,c as d,a3 as c}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Tenant API v1 — Accounting","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Accounting | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-accounting"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Accounting | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-accounting"}]]},"headers":[],"relativePath":"api/tenant-v1-accounting.md","filePath":"api/tenant-v1-accounting.md","lastUpdated":1788177646000}'),a={name:"api/tenant-v1-accounting.md"};function n(r,t,i,s,u,l){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="tenant-api-v1-—-accounting" tabindex="-1">Tenant API v1 — Accounting <a class="header-anchor" href="#tenant-api-v1-—-accounting" aria-label="Permalink to &quot;Tenant API v1 — Accounting&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:accounting</code>, plus <code>can:accounting.*</code>.</p><h2 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/accounts</code></td><td><code>accounting.view</code></td></tr><tr><td>GET</td><td><code>/accounts/stats</code></td><td><code>accounting.view</code></td></tr><tr><td>POST</td><td><code>/accounts</code></td><td><code>accounting.create</code></td></tr><tr><td>GET</td><td><code>/accounts/{account}</code></td><td><code>accounting.view</code></td></tr><tr><td>PUT</td><td><code>/accounts/{account}</code></td><td><code>accounting.update</code></td></tr><tr><td>DELETE</td><td><code>/accounts/{account}</code></td><td><code>accounting.delete</code></td></tr><tr><td>POST</td><td><code>/accounts/{account}/restore</code></td><td><code>accounting.restore</code></td></tr><tr><td>DELETE</td><td><code>/accounts/{account}/force</code></td><td><code>accounting.force.delete</code></td></tr></tbody></table><p>Create body: <code>code</code>, <code>name</code>, <code>type</code> (<code>asset</code>|<code>liability</code>|<code>equity</code>|<code>revenue</code>|<code>expense</code>), optional <code>parent_id</code>, <code>is_active</code>, <code>is_cash_bank</code> (asset only), <code>description</code>.</p><p>List query: optional <code>is_cash_bank=1</code> for deposit/paid-from pickers. List/show include <strong><code>balance</code></strong> (posted journals, signed by account normal balance).</p><p>Listing auto-seeds the starter chart when the tenant has no accounts. Starter Cash <code>1000</code> has <code>is_cash_bank=true</code>.</p><h2 id="account-balance-adjustments" tabindex="-1">Account balance adjustments <a class="header-anchor" href="#account-balance-adjustments" aria-label="Permalink to &quot;Account balance adjustments&quot;">​</a></h2><p>Cash/bank <strong>Set balance</strong> — posts a delta journal; never writes a stored balance column.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/account-balance-adjustments</code></td><td><code>accounting.view</code></td></tr><tr><td>GET</td><td><code>/account-balance-adjustments/{accountBalanceAdjustment}</code></td><td><code>accounting.view</code></td></tr><tr><td>POST</td><td><code>/accounts/{account}/balance-adjustments</code></td><td><code>accounting.create</code></td></tr><tr><td>POST</td><td><code>/account-balance-adjustments/{accountBalanceAdjustment}/void</code></td><td><code>accounting.void</code></td></tr></tbody></table><p>Create body: <code>target_balance</code> (required), <code>entry_date</code>, optional <code>offset_account_id</code> (default system Owner Equity <code>3000</code>), <code>memo</code>, <code>currency</code>. Account must be active cash/bank. <code>delta = target − current</code>; <code>|delta| &lt; 0.01</code> → 422. Increase: Dr account / Cr offset; decrease: Dr offset / Cr account. Numbers <code>ADJ-#####</code>. List query: optional <code>account_id</code>, <code>status</code>, <code>from</code>, <code>to</code>, <code>search</code>. Void body optional <code>void_reason</code>.</p><h2 id="journal-entries" tabindex="-1">Journal entries <a class="header-anchor" href="#journal-entries" aria-label="Permalink to &quot;Journal entries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/journal-entries</code></td><td><code>accounting.view</code></td></tr><tr><td>GET</td><td><code>/journal-entries/stats</code></td><td><code>accounting.view</code></td></tr><tr><td>POST</td><td><code>/journal-entries</code></td><td><code>accounting.create</code></td></tr><tr><td>GET</td><td><code>/journal-entries/{journalEntry}</code></td><td><code>accounting.view</code></td></tr><tr><td>PUT</td><td><code>/journal-entries/{journalEntry}</code></td><td><code>accounting.update</code></td></tr><tr><td>DELETE</td><td><code>/journal-entries/{journalEntry}</code></td><td><code>accounting.delete</code></td></tr><tr><td>POST</td><td><code>/journal-entries/{journalEntry}/restore</code></td><td><code>accounting.restore</code></td></tr><tr><td>DELETE</td><td><code>/journal-entries/{journalEntry}/force</code></td><td><code>accounting.force.delete</code></td></tr><tr><td>POST</td><td><code>/journal-entries/{journalEntry}/post</code></td><td><code>accounting.post</code></td></tr><tr><td>POST</td><td><code>/journal-entries/{journalEntry}/void</code></td><td><code>accounting.void</code></td></tr></tbody></table><p>Create/update body: <code>entry_date</code>, optional <code>memo</code>, <code>lines[]</code> with <code>account_id</code>, <code>debit</code>, <code>credit</code>, optional <code>memo</code> / <code>sort_order</code>. Lines must balance; each line has debit XOR credit. Draft-only edit/delete. Void body optional <code>void_reason</code>.</p><h2 id="account-transfers" tabindex="-1">Account transfers <a class="header-anchor" href="#account-transfers" aria-label="Permalink to &quot;Account transfers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/account-transfers</code></td><td><code>accounting.view</code></td></tr><tr><td>GET</td><td><code>/account-transfers/stats</code></td><td><code>accounting.view</code></td></tr><tr><td>POST</td><td><code>/account-transfers</code></td><td><code>accounting.create</code></td></tr><tr><td>GET</td><td><code>/account-transfers/{accountTransfer}</code></td><td><code>accounting.view</code></td></tr><tr><td>POST</td><td><code>/account-transfers/{accountTransfer}/void</code></td><td><code>accounting.void</code></td></tr></tbody></table><p>Create body: <code>from_account_id</code>, <code>to_account_id</code> (distinct active cash/bank accounts), <code>amount</code>, <code>transferred_at</code>, optional <code>currency</code>, <code>reference</code>, <code>memo</code>. Creates and <strong>posts</strong> a journal (Dr to / Cr from). Status starts <code>posted</code>. Void body optional <code>void_reason</code> — voids the linked journal.</p><h2 id="general-ledger" tabindex="-1">General ledger <a class="header-anchor" href="#general-ledger" aria-label="Permalink to &quot;General ledger&quot;">​</a></h2><h3 id="get-general-ledger" tabindex="-1">GET <code>/general-ledger</code> <a class="header-anchor" href="#get-general-ledger" aria-label="Permalink to &quot;GET `/general-ledger`&quot;">​</a></h3><p>Permission: <code>accounting.view</code>.</p><p>Query: <code>account_id</code>, <code>from</code>, <code>to</code>.</p><p>Response includes <code>opening_balance</code>, <code>closing_balance</code>, and <code>lines</code> (posted only; void excluded).</p><h3 id="get-general-ledger-export" tabindex="-1">GET <code>/general-ledger/export</code> <a class="header-anchor" href="#get-general-ledger-export" aria-label="Permalink to &quot;GET `/general-ledger/export`&quot;">​</a></h3><p>Permission: <code>accounting.view</code>.</p><p>Same query as the inquiry endpoint. Streams a CSV download of <strong>all</strong> matching posted lines (no page-size cap).</p>',26)])])}const g=e(a,[["render",n]]);export{p as __pageData,g as default};
